import { NextResponse } from "next/server";
import { pool } from "@/app/lib/db";

// جلب جميع القطع
export async function GET() {
  try {
    const [rows] = await pool.execute(
      "SELECT * FROM parts ORDER BY created_at DESC"
    );
    return NextResponse.json(rows);
  } catch (error: any) {
    return NextResponse.json(
      { error: "حدث خطأ في جلب البيانات" },
      { status: 500 }
    );
  }
}

// حذف قطعة
export async function DELETE(request: Request) {
  try {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get("id");

    if (!id) {
      return NextResponse.json({ error: "معرف القطعة مطلوب" }, { status: 400 });
    }

    await pool.execute("DELETE FROM parts WHERE id = ?", [id]);
    return NextResponse.json({ message: "تم الحذف بنجاح" });
  } catch (error: any) {
    return NextResponse.json(
      { error: "حدث خطأ أثناء الحذف" },
      { status: 500 }
    );
  }
}

// تعديل قطعة
export async function PUT(request: Request) {
  try {
    const body = await request.json();
    const { id, part_name, make, model, year, vin, price, image_url } = body;

    if (!id) {
      return NextResponse.json({ error: "معرف القطعة مطلوب" }, { status: 400 });
    }

    await pool.execute(
      "UPDATE parts SET part_name = ?, make = ?, model = ?, year = ?, vin = ?, price = ?, image_url = ? WHERE id = ?",
      [part_name, make, model, year, vin, price, image_url || null, id]
    );

    return NextResponse.json({ message: "تم تعديل البيانات بنجاح" });
  } catch (error: any) {
    return NextResponse.json(
      { error: "حدث خطأ أثناء تحديث البيانات" },
      { status: 500 }
    );
  }
}